-- Migration (system): company MFA policy (Phase 4.1 slice S3b-1b, docs/PHASE-4.1.md section 3, decisions D-080, D-167). Forward-only, additive: two tables and rows added to the preset Company Administrator role;
-- nothing existing is dropped or replaced. Opaque physical names (D-029) are generated by tools/schema/system-mfa-policy.cjs (logical dictionary: SystemSchema.MfaPolicy.cs). Do not edit by hand: re-run the generator.
--
-- WHAT THIS IS: the per-company setting MfaPolicy = Off | RequiredForRoles(list) | RequiredForAll. A company with no row has policy Off. The policy is NOT a secret: it is part of the system dump and of every backup.
-- revision: optimistic concurrency of the policy (1 when the row is first written, +1 on every change; a company with no row is at revision 0). The API returns it as the ETag and requires it in If-Match.
-- policy: 0 Off, 1 RequiredForRoles, 2 RequiredForAll. The list of roles of a RequiredForRoles policy is t_3ab20a05; the service keeps it empty for the other two kinds.

CREATE TABLE t_b0a079c7 (
    c_40b06ead uuid NOT NULL,
    c_bf0fe463 smallint NOT NULL,
    c_bdeac2e1 bigint NOT NULL,
    c_f14e8986 timestamptz NOT NULL,
    c_d36db703 uuid NOT NULL,
    CONSTRAINT k_6c7e1ffa PRIMARY KEY (c_40b06ead),
    CONSTRAINT k_88e835ee FOREIGN KEY (c_40b06ead) REFERENCES t_f446f4d0 (c_a9a73285),
    CONSTRAINT k_53ec110a FOREIGN KEY (c_d36db703) REFERENCES t_fc83d26e (c_74b9e5ad),
    CONSTRAINT k_ccc7896f CHECK (c_bf0fe463 IN (0, 1, 2)),
    CONSTRAINT k_6fb13eb7 CHECK (c_bdeac2e1 >= 1)
);

CREATE TABLE t_3ab20a05 (
    c_1c050ac6 uuid NOT NULL,
    c_41c933b1 uuid NOT NULL,
    CONSTRAINT k_aea26fc4 PRIMARY KEY (c_1c050ac6, c_41c933b1),
    CONSTRAINT k_00298467 FOREIGN KEY (c_1c050ac6) REFERENCES t_b0a079c7 (c_40b06ead),
    CONSTRAINT k_d2662fdb FOREIGN KEY (c_41c933b1) REFERENCES t_359332ac (c_59b19fa5)
);
CREATE INDEX k_e036f5b6 ON t_3ab20a05 (c_41c933b1);

REVOKE ALL ON TABLE t_b0a079c7 FROM PUBLIC;
REVOKE ALL ON TABLE t_3ab20a05 FROM PUBLIC;

